import test from 'node:test';
import assert from 'node:assert/strict';
import {encode,decode,walkStates,remapText} from '../shared/paint.js';
import {readProject,convertProject,analyse,MODEL_FILE} from '../shared/project.js';
import {bambuConfig,check} from '../shared/targets.js';
import {editProject} from '../../experiments/workbench/model-edit.js';

// Golden extended states from Bambu Studio 2.9.1 TriangleSelector's repeated
// 0xF-nibble serializer, not values generated by our encoder.
const extended=['EC','0FC','1FC','2FC','3FC','4FC','5FC','6FC'];
const colours=Array.from({length:24},(_,i)=>'#'+((i+1)*650101).toString(16).padStart(6,'0').toUpperCase());
const bytes=text=>new TextEncoder().encode(text);
function fixture(count=24) {
  const objects=Array.from({length:count},(_,i)=>{
    const state=i+1,paint=state>=17?extended[state-17]:encode({kind:'leaf',state});
    const vertices=[[0,0,0],[8,0,0],[0,8,0],[0,0,8]].map(([x,y,z])=>`<vertex x="${x}" y="${y}" z="${z}"/>`).join('');
    const triangles=[[0,2,1],[0,1,3],[0,3,2],[1,2,3]].map(([v1,v2,v3])=>`<triangle v1="${v1}" v2="${v2}" v3="${v3}" paint_color="${paint}"/>`).join('');
    return `<object id="${state}" type="model"><mesh><vertices>${vertices}</vertices><triangles>${triangles}</triangles></mesh></object>`;
  }).join('');
  const items=Array.from({length:count},(_,i)=>`<item objectid="${i+1}" transform="1 0 0 0 1 0 0 0 1 ${(i%6)*15} ${Math.floor(i/6)*15} 0"/>`).join('');
  return new Map([[MODEL_FILE,bytes(`<model unit="millimeter" xmlns="http://schemas.microsoft.com/3dmanufacturing/core/2015/02"><metadata name="Application">BambuStudio-02.09.01.70</metadata><resources>${objects}</resources><build>${items}</build></model>`)],['Metadata/project_settings.config',bytes(JSON.stringify(bambuConfig(colours.slice(0,count),Array(count).fill('PLA'),[])))]]);
}
function setup() {
  const name='Bambu Lab H3C 0.4 nozzle';
  return {machine:{name,printer_model:'Bambu Lab H3C',printer_variant:'0.4',nozzle_diameter:['0.4'],extruder_max_nozzle_count:['9'],printable_area:['0x0','330x0','330x320','0x320'],printable_height:'325'},
    process:{name:'0.20mm Standard @BBL H3C',layer_height:'0.2'},materials:{PLA:{name:'Generic PLA @BBL H3C',compatible_printers:[name],filament_type:['PLA'],filament_extruder_variant:['Direct Drive Standard','Direct Drive High Flow'],nozzle_temperature:['220','225']}},bed:{width:330,depth:320,maxHeight:325,edgeMargin:0}};
}

test('Bambu extended colours 17–24 match upstream paint bytes and survive nested remapping',()=>{
  extended.forEach((value,i)=>{assert.equal(decode(value).state,i+17);assert.equal(encode({kind:'leaf',state:i+17}),value);});
  const tree={kind:'split',sides:2,specialSide:3,children:[{kind:'leaf',state:0},{kind:'leaf',state:17},{kind:'leaf',state:24}]};
  const moved=decode(remapText(encode(tree),{17:24,24:18}));
  assert.equal(moved.specialSide,3);assert.deepEqual(walkStates(moved),[0,24,18]);
  assert.throws(()=>decode('FC'),/ends inside/);
});

test('24 painted colours survive native export, slot swaps and duplicated plate arrangements',()=>{
  const source=readProject(fixture());
  assert.deepEqual(analyse(source,1,null).used,Array.from({length:24},(_,i)=>i+1));
  const rule=Object.fromEntries(Array.from({length:24},(_,i)=>[i+1,24-i]));
  const output=convertProject(source,1,null,{target:'bambu',bambuSetup:setup(),assignmentMode:'slots',mapping:rule,
    layout:{copies:2,arrangement:'objects',spacing:5,width:330,depth:320,tower:false}});
  assert.deepEqual(output.problems,[]);
  const cfg=JSON.parse(new TextDecoder().decode(output.entries.get('Metadata/project_settings.config')));
  assert.equal(cfg.filament_colour.length,24);assert.equal(cfg.filament_settings_id.length,24);
  assert.equal(cfg.filament_self_index.length,48);assert.deepEqual(cfg.nozzle_diameter,['0.4']);
  const reopened=readProject(output.entries);
  assert.equal(reopened.items.length,48);
  assert.deepEqual(analyse(reopened,1,null).used,Array.from({length:24},(_,i)=>i+1));
  assert.deepEqual(reopened.colors,source.colors.toReversed());
});

test('colour editing can add a 24th colour and another output cannot silently truncate it',()=>{
  const source=fixture(23);
  const edited=editProject(source,{objectIds:['1'],operation:'colour',colour:colours[23]});
  const p=readProject(edited.entries);assert.equal(p.colors.length,24);
  assert(analyse(p,1,null).used.includes(24));
  assert.throws(()=>editProject(edited.entries,{objectIds:[edited.changes[0].created[0].id],operation:'colour',colour:'#FFFFFF'}),/24 colours/);
  for(const target of ['snapmaker','prusa','orca'])assert.throws(()=>convertProject(readProject(fixture()),1,null,{target}),/1\.\.16/);
  assert.throws(()=>bambuConfig(Array(25).fill('#FFFFFF'),Array(25).fill('PLA'),[]),/24 ids/);
  assert.throws(()=>check(24,[]),/16 ids/);
});
